  sleep?: (ms: number) => Promise<void>;
  now?: () => number;
  pollIntervalMs?: number;
  /** How long to wait for consensus before giving up waiting (the transaction itself may still finish). */
  maxWaitMs?: number;
  /** How many agreements to read in parallel while scanning. */
  scanBatch?: number;
  /** "final" reads finalized state only. Default "latest" (what the app shows, with non-final data included). */
  readConsistency?: ReadConsistency;
